  --inputs '{"script":"const fields = ($vars.extractInvoiceFields1.output.ExtractionResult && $vars.extractInvoiceFields1.output.ExtractionResult.ResultsDocument && $vars.extractInvoiceFields1.output.ExtractionResult.ResultsDocument.Fields) || [];
const normalizedFields = fields.map(function(f) {
  return {
    Id: f.FieldId,
    Name: f.FieldName,
    Value: (f.Values && f.Values[0] !== undefined) ? f.Values[0] : null,
    Type: f.FieldType,
    Confidence: f.Confidence,
    IsMissing: f.IsMissing
  };
});
const rawInvoiceNumber = (($vars.start.output.webhookPayload.invoice && $vars.start.output.webhookPayload.invoice.invoiceNumber) || "").trim().toUpperCase();
const normalizedInvoiceNumber = rawInvoiceNumber.startsWith("MCS-") ? rawInvoiceNumber : ("MCS-" + rawInvoiceNumber);
return { normalizedFields: normalizedFields, normalizedInvoiceNumber: normalizedInvoiceNumber };"}' \
  --outputs auto

python3 $SCRIPTS/flow_edit.py add-node --flow BillingDisputeResolution.flow --id mergeBranches1 \
  --type core.logic.merge --definition-file /tmp/def_merge.json --label "Merge Lookups" \
  --outputs output

python3 $SCRIPTS/flow_edit.py add-node --flow BillingDisputeResolution.flow --id discrepancyDetection1 \
  --type core.action.script --definition-file /tmp/def_script.json --label "Discrepancy Detection" \
  --inputs '{"script":"const disputedItems = (($vars.start.output.webhookPayload.dispute || {}).disputedLineItems) || [];
const erpRows = $vars.erpLookup1.output || [];
let totalOvercharge = 0;
let totalUndercharge = 0;
const lineDiscrepancies = disputedItems.map(function(item) {
  const erpRow = erpRows.find(function(r) { return r.lineNumber === item.lineNumber; });
  if (!erpRow) {
    return {
      lineNumber: item.lineNumber,
      description: item.description,
      disputedQuantity: item.quantity,
      disputedUnitPrice: item.unitPrice,
      disputedAmount: item.amount,
      contractedUnitPrice: null,
      contractedAmount: null,
      variance: null,
      matched: false
    };
  }
  const variance = item.amount - erpRow.amount;
  if (variance > 0) {
    totalOvercharge += variance;
  } else if (variance < 0) {
    totalUndercharge += Math.abs(variance);
  }
  return {
    lineNumber: item.lineNumber,
    description: item.description,
    disputedQuantity: item.quantity,
    disputedUnitPrice: item.unitPrice,
    disputedAmount: item.amount,
    contractedUnitPrice: erpRow.unitPrice,
    contractedAmount: erpRow.amount,
    variance: variance,
    matched: true
  };
});
const hasDiscrepancies = lineDiscrepancies.some(function(d) { return !d.matched || d.variance !== 0; });
return { lineDiscrepancies: lineDiscrepancies, totalOvercharge: totalOvercharge, totalUndercharge: totalUndercharge, hasDiscrepancies: hasDiscrepancies };"}' \
  --outputs auto

